with deduped as (select * from accounts qualify row_number() over (partition by customer_id order by balance desc nulls first, id) = 1) select date_trunc('week', opened_date) as week_start, customer_id, count(*) filter (where account_type = 'LOAN') as loan_rows, round(sum(balance) / nullif(count(case when status = 'FROZEN' then 1 end), 0), 2) as balance_per_frozen, count(case when account_type = 'LOAN' then 1 end) as loan_count, percent_rank() over (partition by date_trunc('week', opened_date) order by count(case when account_type = 'LOAN' then 1 end) desc) as loan_count_percent_rank from deduped group by 1, 2 order by balance_per_frozen desc nulls first;
